function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw dog
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 70);
  ctx.stroke();

  // draw chasing behavior
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 70);
  ctx.lineTo(W/2 + Math.cos(t) * 100, H/2 + 100);
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 10]);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.lineWidth = 4;

  ctx.restore();
}
